import { getErrorMessage, hasInSet } from "../../common";
import { InAppApiService, ShopPurchaseResult } from "./types";
import { IApiShopItem } from "../../logic";

interface IMockShopServiceProps {
  availablePurchaseIds: string[];
  savePurchaseOnPlayerBalance: (purchaseId: string) => void;
}

export class MockInAppService implements InAppApiService {
  private readonly availablePurchases: Set<IApiShopItem>;

  constructor(private readonly props: IMockShopServiceProps) {
    this.availablePurchases = new Set<IApiShopItem>(
      props.availablePurchaseIds.map((id) => ({
        id,
        price: 320,
        currency: "yan",
      })),
    );
  }

  async preload(): Promise<void> {}

  getShopData(): Set<IApiShopItem> | undefined {
    if (this.availablePurchases.size === 0) return;
    return new Set(this.availablePurchases);
  }

  async shopPurchase(purchaseId: string): Promise<ShopPurchaseResult> {
    if (!hasInSet(this.availablePurchases, (next) => next.id === purchaseId)) {
      return { error: "purchase not configured" };
    }
    try {
      this.props.savePurchaseOnPlayerBalance(purchaseId);
    } catch (e) {
      return { error: getErrorMessage(e), purchaseId };
    }
    return { purchaseId };
  }
}
