import { Align, arrayAlign } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ViewElementBuilder } from "../../assets";
import { SpiderSuitsMode } from "../../common";
import { Scenes } from "../../common/game-core";
import { setSpiderSuitsMode } from "../../logic";
import { GameServiceProvider } from "../../services";
import { spiderModes, spiderModeTitleMap, spiderStartViewUiConstants } from "./constants";

interface IProps {
  scene: Phaser.Scene;
}

export class SpiderStartView {
  constructor(private readonly props: IProps) {
    const { scene } = props;
    const builder = new ViewElementBuilder(scene);
    const align = new Align();

    builder.backgroundStartScene();

    const title = builder.textStartScreenTitle();
    align.anchorSceneScreen(scene).centerX(title).topIn(title, spiderStartViewUiConstants.titleTopOffset);

    const buttons = spiderModes.map((mode) => {
      return builder.buttonPrimary(
        getLocalizedText(spiderModeTitleMap[mode]),
        () => this.startSpiderGame(mode),
        {
          width: spiderStartViewUiConstants.buttonWidth,
          height: spiderStartViewUiConstants.buttonHeight,
          fontSizePx: spiderStartViewUiConstants.buttonFontSizePx,
        },
      );
    });
    const buttonsLayout = arrayAlign.alignObject(arrayAlign.column(buttons, spiderStartViewUiConstants.buttonsGap));
    align
      .anchorSceneScreen(scene)
      .center(buttonsLayout)
      .bottomIn(buttonsLayout, spiderStartViewUiConstants.buttonsBottomOffset);
  }

  private startSpiderGame(suitsMode: SpiderSuitsMode) {
    const { scene } = this.props;
    GameServiceProvider.get().setPlayerData(setSpiderSuitsMode(suitsMode));
    scene.scene.start(Scenes.SpiderGame);
  }
}
