import { ViewElementBuilder } from "../../../../assets";
import {
  createDefaultKlondikeStacksCreator,
  DefaultKlondikeGameMaster,
  DefaultKlondikeStatelessAnimator,
  defaultKlondikeConfig,
  IClassicCardDto,
  KlondikeGameMove,
  KlondikeCard,
  KlondikeStackType,
  KlondikeView,
  TypedEventsEmitter,
} from "../../../../common";
import { IGameLogicCommandEvents, IGameViewEvents } from "../../logic";
import { dealKlondikeCards } from "./components/dealKlondikeCards";
import { playSoundToKlondikeMove } from "./components/playSoundToKlondikeMove";

interface IProps {
  scene: Phaser.Scene;
  gameSceneLogicCommands: TypedEventsEmitter<IGameLogicCommandEvents>;
  gameSceneViewEvents: TypedEventsEmitter<IGameViewEvents>;
}

export class KlondikeWrap {
  private readonly builder: ViewElementBuilder;
  private klondikeView: KlondikeView | undefined;
  private readonly unSubs: Array<() => void> = [];

  constructor(private props: IProps) {
    const { scene } = this.props;
    this.builder = new ViewElementBuilder(scene);
    this.subscribeToLogicCommands();
  }

  /**
   * подписка на команды логики
   * - отписываьться не нужно - логика все почистит
   * **/
  private subscribeToLogicCommands() {
    const { gameSceneLogicCommands } = this.props;
    const getEvents = () => this.klondikeView?.userEvents;
    gameSceneLogicCommands.on("startKlondike", (data) => this.start(data.cards));
    gameSceneLogicCommands.on("undoKlondike", (data) => getEvents()?.emit("onUndoClick"));
    gameSceneLogicCommands.on("hintKlondike", (data) => getEvents()?.emit("onHintClick", data));
    gameSceneLogicCommands.on("visionKlondike", (data) =>
      getEvents()?.emit("onVisionClick", data),
    );
    gameSceneLogicCommands.on("magicKlondike", (data) => getEvents()?.emit("onMagicClick", data));
    gameSceneLogicCommands.on("autoCompleteKlondike", () =>
      this.klondikeView?.runAutoCompleteAnimation(),
    );
  }

  start(playCards: IClassicCardDto[]) {
    this.klondikeView?.destroy();

    const { builder } = this;
    const { scene } = this.props;

    const cardViews = playCards.map(
      ({ value, suit }) =>
        new KlondikeCard({
          scene,
          suit,
          value,
          initStackId: KlondikeStackType.DECK,
          initSide: "back",
          faceImage: builder.cardFace(suit, value),
          backImage: builder.cardBack(),
        }),
    );
    const stackMap = createDefaultKlondikeStacksCreator({
      scene,
      createCardPlace: () => builder.cardPlace(),
    })();

    const gameMaster = new DefaultKlondikeGameMaster({ stackMap });

    const klondikeView = new KlondikeView({
      cardViews,
      stackMap,
      config: defaultKlondikeConfig,
      dealCards: dealKlondikeCards,
      statelessAnimator: new DefaultKlondikeStatelessAnimator(
        defaultKlondikeConfig.statelessAnimationConfig,
      ),
      gameMaster,
    });
    this.subscribeToKlondikeEvents(klondikeView);
    this.klondikeView = klondikeView;
  }

  private subscribeToKlondikeEvents(klondikeView: KlondikeView) {
    const { scene } = this.props;
    const { gameSceneViewEvents } = this.props;

    //  просто озвучка хода
    klondikeView.gameEvents.on("playerCardsMoveStart", (move) => {
      playSoundToKlondikeMove(scene, move);
    });

    // передаем обновления данных выше в логику
    klondikeView.liveState.on((state) => {
      scene.input.enabled = state.step === "idle";
      gameSceneViewEvents.emit("klondikeStateUpdate", state);
    });

    klondikeView.gameEvents.on("onDealFinish", () =>
      gameSceneViewEvents.emit("klondikeDealFinish"),
    );
    klondikeView.gameEvents.on("undoFinish", () => gameSceneViewEvents.emit("klondikeUndoFinish"));
    klondikeView.gameEvents.on("hintFinish", () => gameSceneViewEvents.emit("klondikeHintFinish"));
    klondikeView.gameEvents.on("visionFinish", () =>
      gameSceneViewEvents.emit("klondikeVisionFinish"),
    );
    klondikeView.gameEvents.on("magicFinish", () =>
      gameSceneViewEvents.emit("klondikeMagicFinish"),
    );

    klondikeView.gameEvents.on("undoStart", ({ move, scoreInc }) => {
      playSoundToKlondikeMove(scene, move);
    });

    klondikeView.gameEvents.on("isAllCardsOnBases", () =>
      gameSceneViewEvents.emit("klondikeCompleted"),
    );
    klondikeView.gameEvents.on("playerCardsMoveFinish", (move: KlondikeGameMove) => {
      if (move.type === "deckRecycle") {
        gameSceneViewEvents.emit("klondikeDeckRecycle");
      }
    });
  }

  destroy() {
    this.klondikeView?.destroy();
    this.unSubs.forEach((unSub) => unSub());
  }
}
