import { createSpiderDeck, IClassicCardDto, ISpiderConfig } from "../../../common";

interface ISpiderDealSessionProps {
  spiderConfig: ISpiderConfig;
}

export class SpiderDealSession {
  private currentDeal: IClassicCardDto[] = [];

  constructor(private readonly props: ISpiderDealSessionProps) {}

  nextDeal() {
    this.currentDeal = createSpiderDeck({
      suitsMode: this.props.spiderConfig.suitsMode,
      shuffle: true,
    });
    return [...this.currentDeal];
  }

  replayDeal() {
    if (this.currentDeal.length > 0) {
      return [...this.currentDeal];
    }
    return this.nextDeal();
  }
}
