import { SpiderSuitsMode } from "../../common";
import { GamePlayerData } from "../types";

export function getSpiderSuitsMode(playerData: Pick<GamePlayerData, "spider">): SpiderSuitsMode {
  return playerData.spider.suitsMode;
}

export function setSpiderSuitsMode(suitsMode: SpiderSuitsMode): Pick<GamePlayerData, "spider"> {
  return {
    spider: {
      suitsMode,
    },
  };
}
