import { ShopItemView } from "./ShopItemView";
import { AlignMethod, arrayAlign, layoutChain } from "@kvisaz/phaser-sugar";
import { makeGrid } from "../../common";

/** Раскладка магазина **/
export const layoutShopItems = (shopItemViews: ShopItemView[]) => {
  /** настройки макета **/
  const basicPadding = 16;

  /** раскладываем на группы **/
  const rewards: ShopItemView[] = [];
  const inapps: ShopItemView[] = [];

  shopItemViews.forEach((item) => {
    if (item.shopItem.rewardAdPrice) rewards.push(item);
    else inapps.push(item);
  });

  /** сетка 2 x 2 детей **/
  const firstReward = rewards[0] as ShopItemView|undefined;
  if(firstReward){
    const gridPaddingX = Math.ceil(basicPadding*2);
    const gridPaddingY = Math.ceil(basicPadding*2.2);
    const rewardBounds = firstReward.getBounds();
    const colStep = rewardBounds?.width + gridPaddingX;
    const rowStep = rewardBounds.height + gridPaddingY;
    makeGrid({
      objects: rewards,
      unitInRow: 2,
      colStep,
      rowStep,
    });
  }

  const rewardLayout = arrayAlign.alignObject(rewards);

  /** ряд инаппов **/
  const inappPadding = Math.ceil(basicPadding*2);
  const inappLayout = layoutChain({
    children: inapps,
    alignToAnchor: AlignMethod.BOTTOM_IN,
    alignToNext: AlignMethod.RIGHT_TO,
    nextOffsetX: inappPadding,
  });

  /** и их в дее колонки **/
  const groupPadding = basicPadding*2;
  const commonLayout = layoutChain({
    children: [rewardLayout, inappLayout],
    alignToAnchor: AlignMethod.CENTER_Y,
    alignToNext: AlignMethod.RIGHT_TO,
    nextOffsetX: groupPadding,
  });

  return {
    arrayAlignObject: commonLayout,
    shopItemViews,
  };
};
