import { GameService, IGameServiceOptions } from "./GameService";

export class GameServiceProvider {
  private static gameService?: GameService;

  /** Получить инстанс, предварительно нужно вызвать reset с валидными опциями */
  static get(): GameService {
    if (this.gameService == null) {
      throw new Error("GameServiceProvider not initialized. Call reset() first.");
    }
    return this.gameService;
  }

  static reset(options: IGameServiceOptions): GameService {
    this.gameService = new GameService(options);
    return this.gameService;
  }

  /** вернуть временный сервис с настройками **/
  static getTempService(options: IGameServiceOptions): GameService {
    return new GameService(options);
  }
}
