import { IApiShopItem, IShopItemConfig, ILogicShopItem } from "../types";

export function api2logicItem(
  item: IApiShopItem,
  itemConfigs: IShopItemConfig[],
): ILogicShopItem | undefined {
  const itemConfig = itemConfigs.find((i) => i.id === item.id && i.isPurchase);
  if (!itemConfig) return;
  const shopPack = itemConfig.shopPack;

  /** проверенный ID **/
  return {
    id: item.id,
    price: item.price,
    currency: item.currency,
    rewardAdPrice: false,
    shopPack
  }
}
