    /**
     *  Dialogs
     ***/
    dialogShop({
                   shopItems,
                   onItemBuyClick,
                   onClose,
               }: {
        shopItems: ILogicShopItem[];
        onItemBuyClick: (item: ILogicShopItem) => void;
        onClose?: () => void;
    }) {
        const itemShopViews = shopItems.map((item) => this.shopItem({item, onItemBuyClick}));
        layoutShopItems(itemShopViews);
        const shopContent = new Phaser.GameObjects.Container(this.scene, 0, 0, itemShopViews);
        const contentBounds = shopContent.getBounds();

        const title = getLocalizedText("shop.title");
        const dialogWidth = contentBounds.width + 32;
        const dialogHeight = contentBounds.height + 32 * 2;

        return this.dialogExternalTopTitle({
            content: shopContent,
            title,
            width: dialogWidth,
            height: dialogHeight,
            onClose,
        });
    }

    getConsumableIconAsset(type: ConsumableType): ImageAsset {
        const assetMap: Record<ConsumableType, ImageAsset> = {
            [ConsumableType.UNDO]: AssetsConfig.images.buttonUndo,
            [ConsumableType.HINT]: AssetsConfig.images.buttonHint,
            [ConsumableType.VISION]: AssetsConfig.images.buttonVision,
            [ConsumableType.MAGIC]: AssetsConfig.images.buttonMagic,
        };
        return assetMap[type];
    }

    shopItem(args: { item: ILogicShopItem; onItemBuyClick: (item: ILogicShopItem) => void }) {
        const {item, onItemBuyClick} = args;
        const bgNineSliceAsset = AssetsConfig.images.uiDialogGroupZoneLightNine16;

        const iconBuilder = (type: ConsumableType) => this.image(this.getConsumableIconAsset(type));

        return new ShopItemView({
            scene: this.scene,
            item,
            frameBuilder: (width, height) => this.nineSlice({...bgNineSliceAsset, width, height}),
            videoPlayIconBuilder: () => this.image(AssetsConfig.images.uiButtonPlay).setScale(0.7),
            iconBuilder,
            textShopItemLabel: this.textShopItemLabel.bind(this),
            buttonBuilder: (buttonLabel, options) =>
                this.buttonPrimary(buttonLabel, () => onItemBuyClick(item), options),
        });
    }

    dialogSettings(args: { settings: StateConnector<ISettingsState>; onCloseClick?: () => void }) {
        const title = getLocalizedText("settings.title");
        const dialogWidth = 1100;
        const dialogHeight = 560;
        const contentWidth = 420;
        const contentHeight = 390;

        const contentBg = this.nineSliceDialogGroup(contentWidth, contentHeight);
        const soundSwitch = this.buttonSwitchSound((isOn) => {
            args.settings.setState((prev) => ({
                ...prev,
                isSoundOn: isOn,
                // если звук выключен — выключаем музыку и блокируем кнопку
                isMusicOn: isOn ? prev.isMusicOn : false,
            }));
        });

        const musicSwitch = this.buttonSwitchMusic((isOn) => {
            args.settings.setState((prev) => ({
                ...prev,
                isMusicOn: isOn,
            }));
        });

        const {align} = this;
        const {alignObject, column} = arrayAlign;

        align.anchor(contentBg).center(alignObject(column([soundSwitch, musicSwitch])));
        const dialogContent = this.scene.add.container(0, 0, [contentBg, soundSwitch, musicSwitch]);

        const applyStateToControls = (state: ISettingsState) => {
            soundSwitch.switch(state.isSoundOn);
            const effectiveMusic = state.isSoundOn ? state.isMusicOn : false;
            musicSwitch.switch(effectiveMusic);
            musicSwitch.enable(state.isSoundOn);
        };

        applyStateToControls(args.settings.getState());
        const unSubState = args.settings.on(applyStateToControls);

        const dialog = this.dialogExternalTopTitle({
            beforeOpen: () => applyStateToControls(args.settings.getState()),
            content: dialogContent,
            title,
            width: dialogWidth,
            height: dialogHeight,
            onCloseClick: args.onCloseClick,
        });

        dialog.once(Phaser.GameObjects.Events.DESTROY, unSubState);

        return dialog;
    }

    dialogTopBar(args: { title: string; width: number; onCloseClick: () => void }) {
        const topBarPadding = 16;

        const topBarContent = new Phaser.GameObjects.Container(this.scene, 0, 0);
        const title = this.textDialogTitle(args.title);
        const topBarBg = new Phaser.GameObjects.Zone(
            this.scene,
            0,
            0,
            args.width,
            title.getBounds().height + topBarPadding * 2,
        );
        const closeButton = this.buttonCloseCross(args.onCloseClick);
        const {align} = this;
        align.anchor(topBarBg).center(title);
        align.rightIn(closeButton).centerY(closeButton);
        topBarContent.add([topBarBg, title, closeButton]);

        return topBarContent;
    }

    dialogExternalTopTitle(args: {
        beforeOpen?: () => void;
        onClose?: () => void;
        onCloseClick?: () => void;
        content: Phaser.GameObjects.Container & AlignObject;
        title: string;
        width?: number;
        height?: number;
        isAutoOpen?: boolean;
        isCloseOnOverlayClick?: boolean;
    }) {
        const bgNineAsset = AssetsConfig.images.uiDialogBgLightNine40;
        const padding = 40;
        const dialogAnimationDuration = 150;

        const bgBuilder = (width: number, height: number) =>
            this.nineSlice({
                ...bgNineAsset,
                width,
                height,
                padding,
            });

        const topBarContent = this.dialogTopBar({
            title: args.title,
            width: args.width ?? 1100,
            onCloseClick: closeClick,
        });

        const dialog = new ExternalTopbarDialog({
            topBarContent,
            beforeOpen: args.beforeOpen,
            onClose: args.onClose,
            content: args.content,
            bgBuilder,
            isAutoOpen: args.isAutoOpen,
            width: args.width,
            height: args.height,
            animationDuration: dialogAnimationDuration,
            isCloseOnOverlayClick: args.isCloseOnOverlayClick,
        });

        function closeClick() {
            dialog.close();
            args.onCloseClick?.();
        }

        return dialog;
    }

    dialogCommon(props: Omit<ICommonDialogProps, "bgBuilder">) {
        const bgNineAsset = AssetsConfig.images.uiDialogBgLightNine40;
        const padding = 40;

        const bgBuilder = (width: number, height: number) =>
            this.nineSlice({
                ...bgNineAsset,
                width,
                height,
                padding,
            });

        return new CommonDialog({
            bgBuilder,
            isAutoOpen: true,
            ...props,
        });
    }

