    effectConsumable(props: { type: ConsumableType; durationMs?: number }) {
        const iconAsset = this.getConsumableIconAsset(props.type);
        const icon = this.image(iconAsset);
        icon.setScale(1.5);

        return new EffectOverlay({
            scene: this.scene,
            icon,
            durationMs: props.durationMs,
            overlayAlpha: 0.35,
            textBuilder: (text) =>
                this.textDialogTitle(text, {
                    color: "#ffffff",
                    align: "center",
                }),
        });
    }

    effectOverlay(props: { iconAsset: ImageAsset; durationMs?: number; overlayAlpha?: number }) {
        const icon = this.image(props.iconAsset);
        return new EffectOverlay({
            scene: this.scene,
            icon,
            durationMs: props.durationMs,
            overlayAlpha: props.overlayAlpha ?? 0.2,
            textBuilder: (text) =>
                this.textDialogTitle(text, {
                    color: "#ffffff",
                    align: "center",
                }),
        });
    }

    /**
     *  Sounds
     ***/

    /** hide concrete sounds, use sound fabric like addButtonSound **/
    public addButtonSound<T extends Phaser.GameObjects.GameObject>(button: T): T {
        button.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () =>
            this.scene.sound.play(SoundKey.click),
        );
        button.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () =>
            this.scene.sound.play(SoundKey.cardFlip),
        );
        return button;
    }

