    /**
     *  Texts View Elements
     ***/
    textDecorative(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        const defaultFontSize = "64px";

        function selectFamily(options: ITextBuildProps) {
            if (options.weight === "regular") return AssetsConfig.fonts.Decorative.fontFamily;
            return AssetsConfig.fonts.DecorativeBold.fontFamily;
        }

        const style: Phaser.Types.GameObjects.Text.TextStyle = {
            ...options,
            fontFamily: selectFamily(options),
            fontSize: options.fontSize ?? defaultFontSize,
        };

        return this.scene.add.existing(new Phaser.GameObjects.Text(this.scene, 0, 0, text, style));
    }

    textMain(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        const defaultFontSize = "32px";

        function selectFamily(options: ITextBuildProps) {
            if (options.weight === "bold") return AssetsConfig.fonts.MainBold.fontFamily;
            if (options.weight === "semibold") return AssetsConfig.fonts.MainSemiBold.fontFamily;
            return AssetsConfig.fonts.Main.fontFamily;
        }

        const fontSize = options.fontSize ?? defaultFontSize;

        const style: Phaser.Types.GameObjects.Text.TextStyle = {
            ...options,
            fontFamily: selectFamily(options),
            fontSize,
        };

        return this.scene.add.existing(new Phaser.GameObjects.Text(this.scene, 0, 0, text, style));
    }

