/** приходит от API покупка - подразумевает только рубли **/
export interface IApiShopItem {
  id: string;
  price: number;
  currency: string;
}

/**
 * Работаем с этим в логике
 * - может быть куплен за рубли
 * - может быть также и параллельно за рекламу
 * - может содержать пакет реальных бонусов в игре
 * - очень тяжело сделать универсальным поэтому пусть будет специфичным для игры
 *
 * если нет ни priceLabel, ни isReward - не должен рендериться
 * **/
export interface ILogicShopItem {
  /** id сохраняется для API пунктов равен id из API **/
  id: string;

  /** цена в валюте **/
  price?: number;

  /** обозначение валюты **/
  currency?: string;

  /** можно взять за просмотр рекламы? Не противоречит наличию price **/
  rewardAdPrice: boolean;

  /** собственно что покупаем **/
  shopPack: ShopPack;
}

/**
 *  конфигурация для покупок или показов за рекламу
 * **/
export interface IShopItemConfig {
  /** уникальный, для инаппов должен совпадать с api product id**/
  id: string;

  /** можно взять за просмотр рекламы? Не противоречит наличию isPurchase **/
  isReward?: boolean;

  /** можно купить? Не противоречит наличию isReward **/
  isPurchase?: boolean;

  /** собственно что покупаем **/
  shopPack: ShopPack;
}

/** локальный конфиг игры **/
export interface IShopConfig {
  items: IShopItemConfig[];
}

export enum ConsumableType {
  UNDO = "UNDO",
  HINT = "HINT",
  MAGIC = "MAGIC",
  VISION = "VISION",
}

/** пак с начислением бонусов **/
export type ConsumableShopPack = {
  type: "consumables";
  data: Partial<Record<ConsumableType, number>>;
};
/** пак с отключением назойливой рекламы **/
export type AdFreeShopPack = { type: "ad_free" };

/** общий тип наборово в магазине **/
export type ShopPack = ConsumableShopPack | AdFreeShopPack;

/**
 * Универсальный элемент магазина
 * - может быть куплен за рубли
 * - может быть также и параллельно за рекламу
 * - может содержать пакет реальных бонусов в игре
 * - очень тяжело сделать универсальным поэтому пусть будет специфичным для игры
 *
 * если нет ни priceLabel, ни isReward - не должен рендериться
 * **/
export interface IUnifiedShopItem {
  /** строка цены с обозначением валют - для id из API **/
  priceLabel: string;

  /** можно взять за просмотр рекламы? Не противоречит наличию priceLabel **/
  isReward?: boolean;

  /** собственно что покупаем **/
  shopPack: ShopPack;
}

export interface IUnifiedShopItemWithId extends IUnifiedShopItem {
  /**
   * уникальный id совпадающий с id из API, если такой есть
   * **/
  id: string;
}

export type InAppPurchaseId = "common" | "silver" | "gold";
export type RewardPurchaseId = "undoPack" | "hintPack" | "magicPack" | "visionPack";
export type PurchaseId = InAppPurchaseId | RewardPurchaseId;
export type ConsumableAmounts = Record<ConsumableType, number>;
