import { SDK } from "ysdk";
import {
  ConsumableType,
  ILogicShopItem,
  InAppPurchaseId,
  IShopConfig,
  IShopItemConfig,
} from "../../logic";
import { getErrorMessage } from "../../common";
import { InAppApiService, ShopPurchaseResult } from "./types";
import { isMockShopEnabled } from "../GameService/mockGetters";
import { MockInAppService } from "./MockInAppService";
import { YandexInAppService } from "./YandexInAppService";
import { api2logicItem } from "../../logic/shop/mappers";
import { GameServicePlayerData } from "../GameService/types";
import { IAdService } from "../../common/ads";

type RewardAdResult = { wasShown: boolean; isReward: boolean; error?: string };

type PlayerDataService = {
  setPlayerData(partial: Partial<GameServicePlayerData>): void;
  getPlayerData(): GameServicePlayerData;
};

interface IProps {
  shopConfig: IShopConfig;
  isMockShop?: boolean;
  sdk?: SDK;
  showRewardedAd: () => Promise<RewardAdResult>;
  playerDataService: PlayerDataService;
  adService?: IAdService;
  isRewardAdEnable: () => boolean;
}

/**
 * Магазинчик конкретной игры
 * - держит реестр возможных покупок за валюту и рекламу
 * - обрабатывает клики
 * - зачисляет на баланс
 * **/
export class ShopService {
  private logicShopItems: Record<string, ILogicShopItem>;
  private inAppApiService?: InAppApiService;

  constructor(private props: IProps) {
    this.logicShopItems = {};
  }

  async preload() {
    try {
      await this.initApi();
      /** Если подключили API магазина
       * - проверяем какие покупки доступны, проставляем цены **/
      if (this.inAppApiService) {
        this.initInAppShopItems({
          api: this.inAppApiService,
          shopConfig: this.props.shopConfig,
        });
      }

      /** Если доступна реклама - обновляем покупки за рекламу
       * - проверяем какие покупки доступны, проставляем цены **/
      this.initRewardableShopItems();
    } catch (e) {
      console.warn(e);
    }
  }

  getShopItems(): Record<string, ILogicShopItem> {
    return this.logicShopItems;
  }

  /** Магазин доступен, если
   * - есть покупки
   * - есть покупки за рекламу и разрешена реклама
   * **/
  isShopEnabled(isRewardAdEnabled: boolean): boolean {
    const inAppItems: ILogicShopItem[] = [];
    const rewardItems: ILogicShopItem[] = [];
    Object.values(this.logicShopItems).forEach((item) => {
      const hasPrice = item.price != null && item.currency != null;
      if (hasPrice) inAppItems.push(item);
      if (item.rewardAdPrice) rewardItems.push(item);
    });
    const hasRewards = rewardItems.length > 0;
    const hasInApps = inAppItems.length > 0;

    return (isRewardAdEnabled && hasRewards) || hasInApps;
  }

  async shopPurchase(id: string): Promise<ShopPurchaseResult> {
    if (this.isInAppId(id)) {
      return this.purchaseInApp(id);
    } else {
      return this.purchaseReward(id);
    }
  }

  private async purchaseInApp(id: InAppPurchaseId): Promise<ShopPurchaseResult> {
    if (this.inAppApiService == null) {
      return { error: "shop not available" };
    }
    return await this.inAppApiService.shopPurchase(id);
  }

  private async purchaseReward(id: string): Promise<ShopPurchaseResult> {
    const purchase = this.logicShopItems[id];
    if (purchase == null) {
      return { error: `no reward purchase with id ${id}` };
    }
    const adResult = await this.props.showRewardedAd();
    if (!adResult.isReward) {
      return { error: adResult.error ?? "reward ad not completed", purchaseId: id };
    }
    try {
      this.saveOnPlayerBalance(id);
    } catch (e) {
      return { error: getErrorMessage(e), purchaseId: id };
    }
    return { purchaseId: id };
  }

  private async initApi(): Promise<void> {
    if (this.inAppApiService != null) return;
    if (isMockShopEnabled() || this.props.isMockShop) {
      const availablePurchaseIds = this.props.shopConfig.items
        .filter((item) => item.isPurchase)
        .map((item) => item.id);

      this.inAppApiService = new MockInAppService({
        availablePurchaseIds,
        savePurchaseOnPlayerBalance: this.saveOnPlayerBalance.bind(this),
      });
    } else {
      const { sdk } = this.props;
      if (sdk == null) return;
      this.inAppApiService = new YandexInAppService({
        sdk,
        savePurchaseOnPlayerBalance: this.saveOnPlayerBalance.bind(this),
      });
    }

    try {
      await this.inAppApiService.preload();
    } catch (e) {
      console.warn("inAppApiService preload failed", e);
    }
  }

  private saveOnPlayerBalance(shopItemId: string): void {
    const item = this.logicShopItems[shopItemId];
    if (!item) {
      console.warn("no shop item for id", shopItemId);
      return;
    }
    if (item.shopPack.type !== "consumables") {
      return;
    }
    const consumables = item.shopPack.data;
    if (consumables == null) {
      console.warn("no consumables for shopItemId", shopItemId);
      return;
    }
    this.addOnPlayerBalance(consumables);
  }

  private addOnPlayerBalance(consumablesIncrement: Partial<Record<ConsumableType, number>>): void {
    const { playerDataService } = this.props;
    const newConsumables: Record<ConsumableType, number> = {
      ...playerDataService.getPlayerData().consumables,
    };
    Object.entries(consumablesIncrement).forEach(([key, amount]) => {
      const type = key as ConsumableType;
      const inc = amount ?? 0;
      newConsumables[type] = newConsumables[type] + inc;
    });
    playerDataService.setPlayerData({ consumables: newConsumables });
  }

  private initInAppShopItems({
    api,
    shopConfig,
  }: {
    api: InAppApiService;
    shopConfig: IShopConfig;
  }) {
    const apiShopItems = api.getShopData() ?? [];
    apiShopItems.forEach((apiShopItem) => {
      const logicItem = api2logicItem(apiShopItem, shopConfig.items);
      if (logicItem) {
        this.logicShopItems[logicItem.id] = logicItem;
      }
    });
  }

  private initRewardableShopItems() {
    const { adService } = this.props;
    /** нет рекламного сервиса - не показываем **/
    if (adService == null) return;

    /** добавляем рекламные итемы из конфига **/
    const rewardConfigs = this.getRewardShopItemConfigs();
    console.log('rewardConfigs', rewardConfigs);
    rewardConfigs.forEach((itemConfig) => {
      this.logicShopItems[itemConfig.id] = {
        id: itemConfig.id,
        shopPack: itemConfig.shopPack,
        rewardAdPrice: true,
      };
    });
  }

  private getRewardShopItemConfigs(): IShopItemConfig[] {
    return this.props.shopConfig.items.filter((item) => item.isReward);
  }

  private getInAppShopItemConfig(): IShopItemConfig[] {
    return this.props.shopConfig.items.filter((item) => item.isPurchase);
  }

  private isInAppId(id: string): id is InAppPurchaseId {
    return this.props.shopConfig.items.some((item) => item.id === id && item.isPurchase);
  }
}
