import { Align, arrayAlign } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ViewElementBuilder } from "../../../assets";
import { ExternalTopbarDialog } from "../../../common/game-core/components/ExternalTopbarDialog";
import { OverlayScene } from "../../../common/scenes";
import { resolveConfirmDialogTheme } from "./confirmDialogThemes";
import {
  ConfirmButtonVariant,
  IConfirmDialogRequest,
  IConfirmDialogTheme,
  IConfirmResult,
} from "./types";

interface IProps {
  scene: Phaser.Scene;
}

type ConfirmResultCallback = (result: IConfirmResult) => void;

interface IResolvedConfirmDialogRequest {
  title: string;
  info?: string;
  confirmText: string;
  cancelText: string;
  isCloseOnOverlayClick?: boolean;
}

export class ConfirmDialog {
  private dialog?: ExternalTopbarDialog;
  private pendingCallback?: ConfirmResultCallback;

  constructor(private readonly props: IProps) {}

  confirm(request: IConfirmDialogRequest, onResult: ConfirmResultCallback): void {
    this.clearPendingCallback();
    this.closeActiveDialog();

    const overlayScene = OverlayScene.get(this.props.scene);
    const builder = new ViewElementBuilder(overlayScene);
    const theme = resolveConfirmDialogTheme(request.theme, request.themeOverrides);
    const resolvedRequest = this.resolveRequest(request);

    this.pendingCallback = onResult;

    const content = this.createContent({
      scene: overlayScene,
      builder,
      theme,
      request: resolvedRequest,
    });

    this.dialog = builder.dialogExternalTopTitle({
      title: resolvedRequest.title,
      content,
      width: theme.dialogWidth,
      height: theme.dialogHeight,
      isCloseOnOverlayClick: resolvedRequest.isCloseOnOverlayClick ?? theme.isCloseOnOverlayClick,
      onClose: () => this.finish({ confirmed: false, reason: "dismiss" }),
    });

    this.dialog.show();
  }

  destroy(): void {
    this.clearPendingCallback();
    this.closeActiveDialog();
  }

  private resolveRequest(request: IConfirmDialogRequest): IResolvedConfirmDialogRequest {
    return {
      title: getLocalizedText(request.titleKey),
      info: request.infoKey == null ? undefined : getLocalizedText(request.infoKey),
      confirmText: getLocalizedText(request.confirmKey ?? "ok"),
      cancelText: getLocalizedText(request.cancelKey ?? "cancel"),
      isCloseOnOverlayClick: request.isCloseOnOverlayClick,
    };
  }

  private createContent(props: {
    scene: Phaser.Scene;
    builder: ViewElementBuilder;
    theme: IConfirmDialogTheme;
    request: IResolvedConfirmDialogRequest;
  }): Phaser.GameObjects.Container {
    const { scene, builder, theme, request } = props;
    const align = new Align();

    const content = scene.add.container(0, 0);
    const contentObjects: Phaser.GameObjects.GameObject[] = [];

    const confirmButton = this.createActionButton({
      builder,
      variant: theme.confirmButtonVariant,
      text: request.confirmText,
      onClick: () => {
        this.finish({ confirmed: true, reason: "confirm" });
        this.dialog?.close();
      },
      width: theme.confirmButtonWidth,
      theme,
    });

    const cancelButton = this.createActionButton({
      builder,
      variant: theme.cancelButtonVariant,
      text: request.cancelText,
      onClick: () => {
        this.finish({ confirmed: false, reason: "cancel" });
        this.dialog?.close();
      },
      width: theme.cancelButtonWidth,
      theme,
    });

    const buttons = [cancelButton, confirmButton];
    const buttonsAlignObject = arrayAlign.alignObject(arrayAlign.row(buttons, theme.buttonsGap));
    contentObjects.push(...buttons);

    if (request.info != null && request.info.trim().length > 0) {
      const info = builder.textDialog(request.info, {
        align: "center",
        fixedWidth: theme.contentWidth,
        wordWrap: {
          width: theme.contentWidth,
        },
      });
      align.anchor(info).centerX(buttonsAlignObject).bottomTo(buttonsAlignObject, theme.contentGap);
      contentObjects.push(info);
    }

    content.add(contentObjects);
    return content;
  }

  private createActionButton(props: {
    builder: ViewElementBuilder;
    variant: ConfirmButtonVariant;
    text: string;
    onClick: () => void;
    width: number;
    theme: IConfirmDialogTheme;
  }) {
    const { builder, variant, text, onClick, width, theme } = props;
    const options = {
      width,
      height: theme.buttonHeight,
      fontSizePx: theme.buttonFontSizePx,
    };

    if (variant === "primary") {
      return builder.buttonPrimary(text, onClick, options);
    }

    if (variant === "warning") {
      return builder.buttonWarning(text, onClick, options);
    }

    return builder.buttonSecondary(text, onClick, options);
  }

  private closeActiveDialog() {
    if (this.dialog == null) return;
    const activeDialog = this.dialog;
    this.dialog = undefined;
    activeDialog.destroy();
  }

  private finish(result: IConfirmResult) {
    if (this.pendingCallback == null) return;
    const callback = this.pendingCallback;
    this.pendingCallback = undefined;
    callback(result);
  }

  private clearPendingCallback() {
    this.pendingCallback = undefined;
  }
}
