import {ConfirmDialogThemeName, IConfirmDialogTheme} from "./types";

const basic: IConfirmDialogTheme = {
    dialogWidth: 900,
    dialogHeight: 400,
    contentWidth: 700,
    contentGap: 42,
    buttonsGap: 20,
    isCloseOnOverlayClick: false,
    confirmButtonVariant: "primary",
    cancelButtonVariant: "secondary",
    confirmButtonWidth: 300,
    cancelButtonWidth: 300,
    buttonHeight: 92,
    buttonFontSizePx: 40,
} as const;

const danger: IConfirmDialogTheme = {
    ...basic,
    confirmButtonVariant: "warning",
    cancelButtonVariant: "secondary",
} as const;

const compact: IConfirmDialogTheme = {
    ...basic
} as const;

const confirmDialogThemeMap: Record<ConfirmDialogThemeName, IConfirmDialogTheme> = {
    basic,
    danger,
    compact,
};

export function resolveConfirmDialogTheme(
    theme: ConfirmDialogThemeName = "basic",
    overrides?: Partial<IConfirmDialogTheme>,
): IConfirmDialogTheme {
    return {
        ...confirmDialogThemeMap[theme],
        ...overrides,
    };
}
