import { defaultSpiderConfig, ISpiderConfig } from "../../common";
import { GamePlayerData } from "../types";
import { getSpiderSuitsMode } from "./playerState";

export function makeSpiderConfigByPlayerState(playerData: GamePlayerData): ISpiderConfig {
  const suitsMode = getSpiderSuitsMode(playerData);
  return {
    ...defaultSpiderConfig,
    suitsMode,
  };
}
