import {Align, cssColorToInt} from "@kvisaz/phaser-sugar";
import {ViewElementBuilder} from "../../assets";
import {SpiderWrap} from "./components/SpiderWrap";
import {SpiderCollectButton, SpiderControls, SpiderInfoUi} from "./components/spider-ui";
import {SpiderGameSceneViewLogic} from "./logic";
import {getSceneBounds} from "../../common";
import {makeSpiderConfigByPlayerState} from "../../logic";
import {GameServiceProvider} from "../../services";
import {SettingsUi} from "../shared";
import {Scenes} from "../../common/game-core";

interface IProps {
    scene: Phaser.Scene;
}

export class SpiderGameSceneView {
    private readonly unSubs: Array<() => void> = [];
    private readonly gameLogic: SpiderGameSceneViewLogic;

    constructor(private readonly props: IProps) {
        const {scene} = props;

        const align = new Align();
        const padding = 16;

        const builder = new ViewElementBuilder(scene);
        builder.backgroundGameScene();

        const playerData = GameServiceProvider.get().getPlayerData();
        const spiderConfig = makeSpiderConfigByPlayerState(playerData);
        this.gameLogic = new SpiderGameSceneViewLogic({spiderConfig});
        this.unSubs.push(() => this.gameLogic.destroy());


        const backButton = builder.buttonBack(
            () => scene.scene.start(Scenes.SpiderStart), {confirm: true},
        );
        align.anchorSceneScreen(scene).topIn(backButton, padding).leftIn(backButton, padding);
        this.unSubs.push(() => backButton.destroy());

        const infoUi = new SpiderInfoUi({
            scene,
            gameState: this.gameLogic.observable(),
        });
        align.anchorSceneScreen(scene).topIn(infoUi, padding).centerX(infoUi, padding);
        this.unSubs.push(() => infoUi.destroy());

        const controls = new SpiderControls({
            scene,
            gameState: this.gameLogic.observable(),
            spiderSceneViewEvents: this.gameLogic.spiderSceneViewEvents,
        });
        align.anchor(backButton).bottomTo(controls, padding * 4).leftIn(controls);
        this.unSubs.push(() => controls.destroy());

        const collectButton = new SpiderCollectButton({
            scene,
            gameState: this.gameLogic.observable(),
            spiderSceneViewEvents: this.gameLogic.spiderSceneViewEvents,
        });
        align.anchorSceneScreen(scene).topIn(collectButton, 62).leftIn(collectButton, 760);
        this.unSubs.push(() => collectButton.destroy());

        const settingsUi = new SettingsUi({scene});
        align.anchorSceneScreen(scene).topIn(settingsUi, padding).rightIn(settingsUi, -padding * 2);
        this.unSubs.push(() => settingsUi.destroy());

        const sceneBounds = getSceneBounds(scene);
        const spiderLayoutZoneColor = cssColorToInt("#ded000");
        const spiderLayoutZone = new Phaser.GameObjects.Rectangle(
            scene,
            0,
            0,
            sceneBounds.width,
            sceneBounds.height / 2,
            spiderLayoutZoneColor,
        );
        align.anchorSceneScreen(scene).topIn(spiderLayoutZone, 135).rightIn(spiderLayoutZone, -48);
        // scene.add.existing(spiderLayoutZone);

        const spiderWrap = new SpiderWrap({
            scene,
            layoutZone: spiderLayoutZone,
            spiderSceneLogicCommands: this.gameLogic.spiderSceneLogicCommands,
            spiderSceneViewEvents: this.gameLogic.spiderSceneViewEvents,
        });
        this.unSubs.push(() => spiderWrap.destroy());

        this.gameLogic.startNewGame({shuffleDeck: true});
    }

    destroy() {
        this.unSubs.forEach((u) => u());
    }
}
