import { ExternalTopbarDialog } from "../../../../../../common/game-core";
import { OverlayScene } from "../../../../../../common/scenes";
import { getLocalizedText, ViewElementBuilder } from "../../../../../../assets";
import { FireworksEffect } from "../../../../../../common/animations";
import { SoundKey } from "../../../../../../logic";
import { CardSuit } from "../../../../../../common";
import { Align } from "@kvisaz/phaser-sugar";

export interface IGameFinishData {
  score: number;
}

interface IProps {
  scene: Phaser.Scene;
}

/**
 * Показать результат
 * - показать счет и поздравление
 * **/
export class GameFinishOverlay {
  private dialog?: ExternalTopbarDialog;
  private builder: ViewElementBuilder;
  private onCloseCallback: (() => void) | undefined;
  private fireworks?: FireworksEffect;

  constructor(private props: IProps) {
    /** overlay автоматически отключится вместе со сценой **/
    const parentScene = this.props.scene;
    OverlayScene.attach(parentScene);

    const childScene = OverlayScene.get(this.props.scene);
    this.builder = new ViewElementBuilder(childScene);
  }

  showScreen(data: IGameFinishData, onClose: () => void) {
    /** экран показываем в child **/
    const childScene = OverlayScene.get(this.props.scene);
    this.pauseParentScene();
    childScene.sound.play(SoundKey.fanfare);
    this.create(childScene, data);
    this.onCloseCallback = onClose;
  }

  closeScreen() {
    this.clearScene();
  }

  private clearScene() {
    const childScene = OverlayScene.get(this.props.scene);
    this.dialog?.destroy();
    this.fireworks?.destroy();
    this.fireworks = undefined;
    childScene.children.removeAll();
    this.resumeParentScene();

    /** вызываем рестарт **/
    const cb = this.onCloseCallback;
    this.onCloseCallback = undefined;
    setTimeout(() => cb?.(), 10);
  }

  /***
   Private
   ***/

  /** создать в child scene **/
  private create(scene: Phaser.Scene, data: IGameFinishData) {
    this.dialog?.destroy();
    const dialogContent = this.createDialogContent(scene, data);
    this.dialog = this.createDialog(scene, dialogContent);
    this.dialog.show();
    this.createFireworks(scene);
  }

  private pauseParentScene() {
    this.props.scene.scene.pause();
  }

  private resumeParentScene() {
    this.props.scene.scene.resume();
  }

  private createDialog(scene: Phaser.Scene, dialogContent: Phaser.GameObjects.Container) {
    const builder = new ViewElementBuilder(scene);

    const title = getLocalizedText("gameOver.congratulation");
    const dialogWidth = 900;
    const dialogHeight = 500;

    const onClose = () => {
      this.clearScene();
    };

    const dialog = builder.dialogExternalTopTitle({
      content: dialogContent,
      title,
      width: dialogWidth,
      height: dialogHeight,
      onClose,
      isCloseOnOverlayClick: true
    });
    return dialog;
  }

  private createDialogContent(scene: Phaser.Scene, data: IGameFinishData) {
    const content = new Phaser.GameObjects.Container(scene);
    const { builder } = this;

    /** scoreText **/
    const scoreText = getLocalizedText("score");
    const scoreTextView = builder.textDialog(scoreText, {
      color: "rgb(0,0,0)",
      weight: "semibold",
      fontSize: "48px",
    });

    const scoreValue = `${data.score}`;
    const scoreValueView = builder.textDialog(scoreValue, {
      color: "rgb(251,182,1)",
      weight: "semibold",
      fontSize: "72px",
    });

    /** bg **/
    const bg = new Phaser.GameObjects.Rectangle(this.props.scene, 0, 0, 300, 100);

    /** figures **/
    const queenFigure = builder.cardFigure(CardSuit.diamond, "queen");
    const jackFigure = builder.cardFigure(CardSuit.heart, "jack");

    /** button close **/
    const button = builder.buttonNewGame(()=>{
      this.dialog?.close()
    });


    const align = new Align();
    align.anchor(bg).center(scoreTextView, 0, -90);
    align.anchor(scoreTextView).centerX(scoreValueView).bottomTo(scoreValueView);
    align.anchor(scoreValueView).centerX(button).bottomTo(button, 32);

    align.anchor(bg);
    const paddingFig = 52;
    align.rightTo(queenFigure, -paddingFig).centerY(queenFigure)
    align.leftTo(jackFigure, paddingFig).centerY(jackFigure)

    content.add([bg, scoreTextView, scoreValueView, queenFigure, jackFigure, button]);
    return content;
  }

  private createFireworks(scene: Phaser.Scene) {
    this.fireworks?.destroy();
    const { builder } = this;
    const { textureName, frameNames } = builder.getGameFinishFireworksImages();
    this.fireworks = new FireworksEffect({
      scene,
      textureName,
      frameNames,
      particleOptions: {
        scale: { min: 0.6, max: 0.8 },
        rotate: { start: 0, end: 120 },
        quantity: 8,
        lifespan: { min: 1200, max: 2000 },
        speed: { min: 600, max: 1000 },
        gravityY: 560,
        frequency: 1200,
      }
    });
    this.fireworks.start();
  }
}
